let data=null,config=null,token='',busy=false,view='overview',page=0,group='sessions',sort='activity',sortDirection='desc',chartMetric='tokens',chartPeriod='day',selectedChartBucket=null,overviewVisual='chart',calendarMetric='tokens',calendarRangeMode='selection',comparisonEnabled=false,comparisonMetric='tokens',comparisonDimension='repository',comparisonSort='delta',comparisonSortDirection='desc',limitHistoryTool='',limitHistoryMode='cost',limitHistoryAggregation='window',limitHistorySort='observed',limitHistorySortDirection='desc',limitHistoryPeriod='30',limitHistoryFrom='',limitHistoryTo='',limitHistoryVisibleWindows=new Set([300,10080]),unknownPriceSort='requests',unknownPriceSortDirection='desc',toastTimer,priceSyncBusy=false,priceSyncMessage='',detailViews,restorePreviewId='';
