async function api(url,body) {const r=await fetch(url,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Atlas-Token':token},body:body===undefined?undefined:JSON.stringify(body)});const x=await r.json();if(!r.ok)throw Error(x.error||'Anfrage fehlgeschlagen.');if(url==='/api/settings'&&x.rates&&config)config.rates=x.rates;return x;}
async function binaryApi(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Atlas-Token':token},body});if(!r.ok){let message='Anfrage fehlgeschlagen.';try{message=(await r.json()).error||message;}catch{}throw Error(message);}return r;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function error(text){$('#error').hidden=!text;$('#error').textContent=text||'';}
function active(){return document.visibilityState==='visible'&&document.hasFocus();}
function live(){const el=$('#live-status');const on=active();el.classList.toggle('paused',!on);el.textContent=busy?'Wird aktualisiert …':on?`Live · ${config?.settings.intervalSeconds||30} s`:'Im Hintergrund pausiert';}
const polling=createPolling({isActive:()=>active()&&!!config,delay:()=>config.settings.intervalSeconds*1000,refresh:()=>refresh(false),onState:live});
function schedule(){polling.schedule();}
async function refresh(manual=true){if(busy||(!manual&&!active())||!config)return;busy=true;$('#refresh').disabled=true;live();try{data=await api('/api/refresh',{});limitHistoryCache.clear();error('');updateFilters();render();detailViews?.dataChanged();const tools=activeTools(),alerts=(data.limitAlerts||[]).filter(alert=>tools.includes(alert.tool));if(alerts.length)toast(alerts.map(alert=>`${toolName(alert.tool)} · ${alert.windowMinutes===300?'5 Stunden':'Wöchentlich'} bei ${alert.usedPercent.toLocaleString('de-DE')} %`).join(' · '));else if(manual)toast('Session-Daten sind aktuell.');}catch(e){error(`Aktualisierung fehlgeschlagen: ${e.message}`);}finally{busy=false;$('#refresh').disabled=false;schedule();}}
document.addEventListener('visibilitychange',polling.visibilityChanged);window.addEventListener('focus',polling.visibilityChanged);window.addEventListener('blur',polling.pause);
function bounds(){return rangeForPeriod($('#period').value,{from:$('#from').value,to:$('#to').value});}
function filterScope(){return {bounds:bounds(),tool:$('#tool').value,repository:$('#repository').value,model:$('#model').value,query:$('#search').value.trim().toLowerCase()};}
function filtered(range=bounds()){return data?filterSessions(visibleSessions(data.sessions),filterScope(),range):[];}
function scopedSessions(){return chartScopedSessions(filtered(),view,selectedChartBucket,chartPeriod);}
function hasSelectionFilter(){return $('#tool').value!=='all'||$('#repository').value!=='all'||$('#model').value!=='all'||!!$('#search').value.trim()||!!selectedChartBucket;}
function updateFilterReset(){const button=$('#reset-filter-selection'),active=hasSelectionFilter();button.disabled=!active;button.title=active?'Ausgewählte Projekte, Modelle, KI-Tools, Suche und Diagrammabschnitte zurücksetzen':'Keine Auswahlfilter aktiv';}
function clearSelectionFilters(){$('#tool').value='all';$('#repository').value='all';$('#model').value='all';$('#search').value='';selectedChartBucket=null;}
function resetAllFilters(){clearSelectionFilters();$('#period').value='all';$('#custom-dates').hidden=true;overviewVisual='chart';calendarRangeMode='selection';comparisonEnabled=false;}
function totals(events){return sumEvents(events);}
function costText(t){return t.unknown===t.requests&&t.requests>0?'–':money(t.cost);}
function plainCostText(t){return !t||t.unknown===t.requests&&t.requests>0?'–':money(t.cost);}
function updateFilters(){const sessions=visibleSessions(data.sessions),tools=activeTools(),tool=$('#tool'),toolValue=tool.value;tool.innerHTML='<option value="all">Alle KI-Tools</option>'+tools.map(value=>`<option value="${value}">${toolName(value)}</option>`).join('');tool.value=tools.includes(toolValue)?toolValue:'all';tool.closest('label').hidden=tools.length<2;const repos=$('#repository'),repoValue=repos.value;repos.innerHTML='<option value="all">Alle Repositories</option>'+[...new Set(sessions.map(s=>s.repository).filter(Boolean))].sort().map(r=>`<option value="${esc(r)}">${esc(basename(r))}</option>`).join('');repos.value=[...repos.options].some(o=>o.value===repoValue)?repoValue:'all';const models=$('#model'),modelValue=models.value;models.innerHTML='<option value="all">Alle Modelle</option>'+[...new Set(sessions.flatMap(s=>s.events.map(e=>e.model)).filter(Boolean))].sort().map(model=>`<option value="${esc(model)}">${esc(model)}</option>`).join('');models.value=[...models.options].some(o=>o.value===modelValue)?modelValue:'all';$('#session-count').textContent=sessions.length;}
function metrics(sessions){const all=sessions.flatMap(s=>s.events),t=totals(all),providerTotals=Object.fromEntries(activeTools().map(tool=>[tool,totals(sessions.filter(s=>s.tool===tool).flatMap(s=>s.events))])),providerNote=activeTools().map(tool=>`<span class="${tool}">${compact(providerTotals[tool].tokens)} ${tool==='codex'?'Codex':'Claude'}</span>`).join(' &nbsp; / &nbsp; '),ratio=t.input+t.cache+t.write?t.cache/(t.input+t.cache+t.write)*100:0;return `<section class="metrics" aria-label="Kennzahlen"><div class="metric"><div class="metric-label">Verbrauchte Tokens</div><div class="metric-value">${compact(t.tokens)}</div><div class="metric-note">${providerNote}</div></div><div class="metric"><div class="metric-label">Geschätzte API-Kosten</div><div class="metric-value">${costText(t)}</div><div class="metric-note">${t.unknown?`${num(t.unknown)} Antworten ohne bekannten Preis · `:''}Schätzung; tatsächlicher Wert kann höher liegen</div></div><div class="metric"><div class="metric-label">Sessions im Zeitraum</div><div class="metric-value">${num(sessions.length)}</div><div class="metric-note">In ${new Set(sessions.map(s=>s.repository)).size} Repositories</div></div><div class="metric"><div class="metric-label">Aus dem Cache</div><div class="metric-value">${ratio.toLocaleString('de-DE',{maximumFractionDigits:1})}<span style="font-size:21px"> %</span></div><div class="metric-note">${compact(t.cache)} gecachte Input-Tokens</div></div></section>`;}
// The chart keeps a fixed coordinate width and is fitted with preserveAspectRatio="meet", so only
// a coordinate height matching the box aspect fills the panel instead of letterboxing beside the
// taller limits panel. The height therefore follows the measured box; 220 is the unstretched ratio.
const chartWidth=730;
let chartHeight=220,chartSessions=null,chartFitFrame=0;
function fitChart(){
 const wrap=$('.dashboard-grid .chart-wrap');if(!wrap||!chartSessions)return;
 const style=getComputedStyle(wrap);
 const w=wrap.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight);
 const h=wrap.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom);
 if(!(w>0)||!(h>0))return;
 // Below the two-column breakpoint the panel is not stretched to a neighbour, so the ratio stays.
 const target=innerWidth>960?Math.round(Math.min(900,Math.max(220,chartWidth*h/w))):220;
 if(Math.abs(target-chartHeight)<=2)return;
 chartHeight=target;wrap.closest('.panel').outerHTML=chart(chartSessions);
}
addEventListener('resize',()=>{cancelAnimationFrame(chartFitFrame);chartFitFrame=requestAnimationFrame(fitChart);});
function bucketKey(time){return periodKey(time,chartPeriod);}
function chart(sessions){const events=sessions.flatMap(s=>s.events.map(e=>({...e,tool:s.tool})));const buckets=new Map();let {start,end}=bounds();if(start===0)start=events.length?events.reduce((min,e)=>Math.min(min,Date.parse(e.time)),Infinity):Date.now()-6*86400000;
 let cursor=new Date(bucketKey(start)+'T00:00:00');let count=0;while(cursor.getTime()<=end&&count++<400){buckets.set(bucketKey(cursor),{codex:0,claude:0});if(chartPeriod==='month')cursor.setMonth(cursor.getMonth()+1);else cursor.setDate(cursor.getDate()+(chartPeriod==='week'?7:1));}
 for(const e of events){const key=bucketKey(e.time);if(!buckets.has(key))buckets.set(key,{codex:0,claude:0});buckets.get(key)[e.tool]+=chartMetric==='cost'?(e.cost||0):e.input+e.cache+e.write+e.output;}
 let rows=[...buckets].sort(([a],[b])=>a.localeCompare(b)).map(([key,value])=>({key,...value}));const overflow=rows.length>90;if(overflow)rows=rows.slice(-90);
 const fmt=v=>chartMetric==='cost'?money(v):compact(v);
 if(selectedChartBucket&&!rows.some(row=>row.key===selectedChartBucket))selectedChartBucket=null;
 const tools=activeTools(),svg=seriesChart({rows,format:fmt,period:chartPeriod,width:chartWidth,height:chartHeight,idPrefix:'chart-main',title:`${chartMetric==='cost'?'Kosten':'Tokenverbrauch'} im Zeitverlauf`,selectable:true,selectedKey:selectedChartBucket,tools});
 const viewSwitch='<div class="segments overview-view-switch" aria-label="Übersichtsdarstellung"><button data-overview-visual="chart" class="active">Verlauf</button><button data-overview-visual="calendar">Kalender</button></div>',legend=tools.map(tool=>`<span class="legend-item"><i class="dot ${tool}"></i>${toolName(tool)}</span>`).join(''),t=totals(events);return `<section class="panel"><div class="panel-head"><div><h2>Nutzung im Verlauf</h2></div><div class="panel-controls">${viewSwitch}<div class="segments" aria-label="Diagramm-Metrik"><button data-metric="tokens" class="${chartMetric==='tokens'?'active':''}">Tokens</button><button data-metric="cost" class="${chartMetric==='cost'?'active':''}">Kosten</button></div></div></div><div class="chart-legend">${legend}<div class="segments" style="margin-left:auto;margin-top:-5px"><button data-bucket="day" class="${chartPeriod==='day'?'active':''}">Tag</button><button data-bucket="week" class="${chartPeriod==='week'?'active':''}">Woche</button><button data-bucket="month" class="${chartPeriod==='month'?'active':''}">Monat</button></div></div><div class="chart-wrap" data-tip-host>${svg}</div><div class="chart-summary"><span>${overflow?'Letzte 90 Zeitabschnitte · für mehr Verlauf „Monat“ wählen':`${num(t.requests)} erfasste Modellantworten`}</span><span>Output <strong>${compact(t.output)}</strong> &nbsp; Cache <strong>${compact(t.cache)}</strong></span></div></section>`;}
function calendar(sessions){const years=[...new Set(visibleSessions(data.sessions).flatMap(session=>session.events.map(event=>new Date(event.time).getFullYear())).filter(Number.isFinite))].sort((a,b)=>b-a);return activityCalendarView({sessions,range:bounds(),metric:calendarMetric,selectedKey:selectedChartBucket,rangeMode:calendarRangeMode,years,num,compact,money,tools:activeTools()});}
function windowCosts(tool,window,now=Date.now()){const range=rangeForLimitWindow(window,{now});return range?totals(data.sessions.filter(s=>s.tool===tool).flatMap(s=>s.events).filter(e=>{const time=Date.parse(e.time);return time>=range.start&&time<=range.end;})):null;}
function limits(){const all=Object.values(data.limits||{}),now=Date.now();function line(w,label,empty,tool){const used=w?.used_percent,reset=w?.resets_at?new Date(w.resets_at*1000):null,expired=reset&&reset.getTime()<=now,known=typeof used==='number'&&Number.isFinite(used)&&!expired,range=rangeForLimitWindow(w,{now});
  const tip={title:`${toolName(tool)} · ${label}`,rows:[['Genutzt',known?`${used.toLocaleString('de-DE')} %`:'Unbekannt'],['Frei',known?`${Math.max(0,100-used).toLocaleString('de-DE')} %`:'Unbekannt'],['Fensterbeginn',range?date(range.start):'Unbekannt'],['Bekannte Kosten im Fenster',plainCostText(windowCosts(tool,w,now))]],note:reset?`${expired?'Reset vorbei · neuer Messwert fehlt':`Reset ${date(reset)}`}`:empty};
  return `<div class="limit-line"><span>${label}</span><strong>${known?`${used.toLocaleString('de-DE')} %`:'Unbekannt'}</strong></div><div class="track" ${tipAttr(tip)}><i class="${used>=90?'danger':used>=75?'warning':''}" style="width:${known?Math.max(0,Math.min(100,used)):0}%"></i></div><div class="reset-note">${reset?`${expired?'Reset vorbei · neuer Messwert fehlt':'Reset'} ${date(reset)}`:empty}</div>`;}
 function group(tool,empty){
  const r=all.find(x=>x.limit_id===tool)||(tool==='codex'?all.find(x=>!x.limit_id):null);
  const primary=[r?.primary,r?.secondary].find(w=>w?.window_minutes===300),secondary=[r?.primary,r?.secondary].find(w=>w?.window_minutes===10080);
  return `<div class="limit-group"><div class="provider-heading">${toolTag(tool)}<span class="plan">${esc(r?.plan_type||'Lokal')}</span></div>${line(primary,'5 Stunden',empty,tool)}${line(secondary,'Wöchentlich',empty,tool)}<div class="rolling-costs"><span>5h <strong>${plainCostText(windowCosts(tool,primary,now))}</strong></span><span>Woche <strong>${plainCostText(windowCosts(tool,secondary,now))}</strong></span></div><button class="limit-history-button" data-limit-history="${tool}" type="button">Kostenlimits &amp; Verlauf</button></div>`;
 }
 const tools=activeTools();if(!tools.length)return '';
 const empty={codex:'Kein Limit-Messwert im Log',claude:'Kein Limit-Messwert in der Claude-Konfiguration'};return `<section class="panel limits-panel ${tools.length===1?'single-provider':''}" data-tip-host><h2>Deine Usage-Fenster</h2>${tools.map(tool=>group(tool,empty[tool])).join('')}</section>`;
}
function grouped(sessions,kind){return groupRows(sessions,kind);}
function tableSortValue(row,key,kind){const isSession=kind==='sessions',cache=row.input+row.cache+row.write?row.cache/(row.input+row.cache+row.write):0;if(key==='name')return isSession?(row.title||basename(row.cwd)):(kind==='tool'?toolName(row.name):kind==='repository'?basename(row.name):row.name);if(key==='tool')return isSession?toolName(row.tool):[...row.tools].map(toolName).join(', ');if(key==='context')return `${basename(row.repository)} ${row.branch||''} ${row.events.map(event=>event.model).join(' ')}`;if(key==='sessions')return row.sessions.size;if(key==='tokens')return row.tokens;if(key==='cost')return row.unknown===row.requests&&row.requests?null:row.cost;if(key==='cache')return cache;return Date.parse(row.lastActivity||0);}
function sorted(rows,kind){return sortRows(rows,sort,sortDirection,(row,key)=>tableSortValue(row,key,kind));}
function table(sessions){let kind=view==='models'?'model':view==='repositories'?'repository':group;if(kind==='tool'&&activeTools().length<2){kind='sessions';group='sessions';}if(kind==='tasks')return taskView({sessions,allSessions:visibleSessions(data.sessions),sort,esc,num,compact,costText,basename,toolTag,date});const isSession=kind==='sessions',allowedSorts=new Set(isSession?['name','tool','context','tokens','cost','activity']:['name','sessions','tool','tokens','cost','cache']);if(!allowedSorts.has(sort)){sort=isSession?'activity':'tokens';sortDirection='desc';}const rows=sorted(grouped(sessions,kind),kind);page=Math.min(page,Math.max(0,Math.ceil(rows.length/pageSize)-1));const shown=rows.slice(page*pageSize,(page+1)*pageSize);let body='';for(const row of shown){if(isSession){const recent=Date.now()-Date.parse(row.lastActivity)<5*60000;body+=`<tr><td><div class="session-cell"><span class="session-symbol">▤</span><button class="row-button" data-session="${esc(row.id)}"><span class="row-title">${esc(row.title||basename(row.cwd))}${recent?'<span class="active-pill">Zuletzt aktiv</span>':''}</span><span class="row-subtitle">${esc(row.sessionId.slice(0,18))}${row.subagent?' · Subagent':''}</span></button></div></td><td>${toolTag(row.tool)}</td><td><span class="repo-name" title="${esc(row.repository)}">${esc(basename(row.repository))}</span><span class="row-subtitle">${esc(row.branch||[...new Set(row.events.map(e=>e.model))].join(', ')||'Keine Nutzungsdaten protokolliert')}</span></td><td class="numeric"><strong>${row.requests?compact(row.tokens):'–'}</strong></td><td class="numeric">${row.requests?costText(row):'–'}</td><td class="numeric muted">${date(row.lastActivity)}</td></tr>`;}else{const label=kind==='tool'?toolName(row.name):kind==='model'?row.name:kind==='repository'?basename(row.name):row.name,subtitle=kind==='tool'?'Alle zugehörigen Sessions':kind==='model'?[...row.tools].map(toolName).join(', '):kind==='repository'?row.name:kind==='branch'?'Sessions auf diesem Branch':'Hauptsession oder Subagent';body+=`<tr><td><button class="row-button aggregate-row-button" data-group-kind="${kind}" data-group-key="${esc(row.name)}"><span class="row-title">${esc(label)}</span><span class="row-subtitle" title="${esc(row.name)}">${esc(subtitle)}</span></button></td><td class="numeric">${num(row.sessions.size)}<span class="row-subtitle">Sessions</span></td><td>${[...row.tools].map(toolTag).join(' ')}</td><td class="numeric"><strong>${compact(row.tokens)}</strong></td><td class="numeric">${costText(row)}</td><td class="numeric muted">${row.input+row.cache+row.write?(row.cache/(row.input+row.cache+row.write)*100).toFixed(1):0} % Cache</td></tr>`;}}
 const heading=view==='repositories'?'Verbrauch nach Projekt':view==='models'?'Verbrauch nach Modell':kind==='sessions'?'Deine Sessions':'Gruppierte Auswertung',groupChoices=[['sessions','Einzelne Sessions'],['tasks','Aufgaben mit Agents'],['repository','Nach Repository'],['tool','Nach KI-Tool'],['model','Nach Modell'],['branch','Nach Branch'],['agent','Hauptsessions / Subagents']].filter(([value])=>value!=='tool'||activeTools().length>1),groups=`<select id="group" aria-label="Gruppierung">${groupChoices.map(([v,t])=>`<option value="${v}" ${kind===v?'selected':''}>${t}</option>`).join('')}</select>`;
 const head=(label,key,numeric=false)=>sortableHeader(label,key,{activeKey:sort,direction:sortDirection,context:'main',numeric});
 const firstLabel=isSession?'Session':kind==='model'?'Modell':kind==='repository'?'Repository':kind==='branch'?'Branch':kind==='agent'?'Sessiontyp':'KI-Tool';
 return `<section class="panel data-table-panel"><div class="panel-head"><div><h2>${heading}</h2><p>${num(rows.length)} ${isSession?'Sessions':'Gruppen'}</p></div><div class="table-toolbar">${['overview','sessions'].includes(view)?groups:''}</div></div>${rows.length?`<div class="table-wrap"><table><thead><tr>${head(firstLabel,'name')}${head(isSession?'KI-Tool':'Sessions',isSession?'tool':'sessions',!isSession)}${head(isSession?'Repository / Modell':'KI-Tools',isSession?'context':'tool')}${head('Tokens','tokens',true)}${head('API-Kosten','cost',true)}${head(isSession?'Letzte Aktivität':'Cache-Anteil',isSession?'activity':'cache',true)}</tr></thead><tbody>${body}</tbody></table></div><div class="table-footer"><span>${page*pageSize+1}–${Math.min((page+1)*pageSize,rows.length)} von ${rows.length}</span><div class="pagination"><button data-page="-1" ${page===0?'disabled':''} aria-label="Vorherige Seite">‹</button><span>Seite ${page+1} / ${Math.ceil(rows.length/pageSize)}</span><button data-page="1" ${(page+1)*pageSize>=rows.length?'disabled':''} aria-label="Nächste Seite">›</button></div></div>`:empty()}</section>`;
}
function empty(){const none=!visibleSessions(data.sessions).length,providers=activeTools().map(toolName).join(' oder ');return `<div class="empty"><span aria-hidden="true">▱</span><h2>${none?'Noch keine Sessions gefunden':'Keine Sessions für diese Auswahl'}</h2><p>${none?`Starte eine Session mit ${esc(providers)}. Falls du andere Datenordner verwendest, trage sie in den Einstellungen ein.`:'Passe den Zeitraum oder die Filter an, um weitere Sessions anzuzeigen.'}</p>${none?'<a class="button" href="#settings">Datenquellen einstellen</a>':'<button class="button secondary" id="reset-filters">Filter zurücksetzen</button>'}</div>`;}
const share=(value,total)=>`${(total?value/total*100:0).toLocaleString('de-DE',{maximumFractionDigits:1})} %`;
function insights(sessions){const all=grouped(sessions,'repository').sort((a,b)=>b.tokens-a.tokens),groups=all.slice(0,4);const max=Math.max(1,...groups.map(g=>g.tokens)),sum=all.reduce((total,g)=>total+g.tokens,0);
 const row=g=>{const tip={title:g.name,rows:[['Tokens',compact(g.tokens)],['API-Kosten',costText(g)],['Sessions',num(g.sessions.size)],['Modellantworten',num(g.requests)]],total:['Anteil',share(g.tokens,sum)],note:`Letzte Aktivität ${date(g.lastActivity)}`};
  return `<div class="insight-row" ${tipAttr(tip)}><div><span class="row-title">${esc(basename(g.name))}</span><div class="track"><i style="width:${g.tokens/max*100}%;background:#9cafea"></i></div></div><div style="text-align:right"><strong>${compact(g.tokens)}</strong><div class="row-subtitle">${g.sessions.size} Sessions</div></div><div style="text-align:right"><strong>${costText(g)}</strong><div class="row-subtitle">API-Schätzung</div></div></div>`;};
 return `<section class="panel overview-bottom" data-tip-host><div class="panel-head"><div><h2>Wo deine KI arbeitet</h2><p>Repositories mit dem höchsten Tokenverbrauch</p></div><a href="#repositories">Alle Repositories ansehen</a></div><div class="group-card-list">${groups.map(row).join('')}</div></section>`;}
function priceStatusText(){const p=config.pricing;const rows=p?.sources?.filter(s=>s.fetchedAt)||[];return rows.length?rows.map(s=>s.name+': abgerufen '+date(s.fetchedAt)).join(' · ')+' · '+num(p.modelCount)+' Modelle im lokalen Preiscache':'Noch kein Online-Abruf. Mitgelieferte Preise sind aktiv.';}
function updatePriceSyncUI(){const button=$('#sync-prices');if(!button)return;button.disabled=priceSyncBusy;button.textContent=priceSyncBusy?'Preise werden abgerufen …':'Preise aktualisieren';$('#price-sync-status').textContent=priceStatusText();$('#price-sync-notice').textContent=priceSyncMessage;$('#price-sync-notice').hidden=!priceSyncMessage;const list=$('#effective-prices');if(list)list.textContent=JSON.stringify(config.rates,null,2);}
function priceHistoryPanel(){const snapshots=config.priceHistory?.snapshots||data?.priceHistory?.snapshots||[],options=snapshots.map(item=>`<option value="${esc(item.id)}">${esc(date(item.validFrom))} · ${esc(item.source||'Lokal')}</option>`).join('');return `<div class="settings-block"><div class="settings-block-head"><div><h3>Historische Preisstände</h3><p>Lokale Stände machen frühere Kostenberechnungen reproduzierbar.</p></div><span class="settings-count">${num(snapshots.length)} Stände</span></div><details class="settings-disclosure"><summary>Preisstände verwalten</summary><div class="price-history-list">${[...snapshots].reverse().slice(0,12).map(item=>`<div><strong>${esc(date(item.validFrom))}</strong><span>${esc(item.source||'Lokal')} · ${num(item.modelCount)} Modelle · Regel ${esc(item.ruleVersion)}</span><code>${esc(item.id)}</code></div>`).join('')||'<p class="help">Noch kein Preisstand gespeichert.</p>'}</div>${snapshots.length>1?`<details class="price-compare"><summary>Preiseffekt vergleichen</summary><label>Erster Preisstand<select id="price-compare-first">${options}</select></label><label>Zweiter Preisstand<select id="price-compare-second">${options}</select></label><div class="price-compare-dates"><label>Von<input id="price-compare-from" type="date" value="${day(Date.now()-29*86400000)}"></label><label>Bis<input id="price-compare-to" type="date" value="${day(Date.now())}"></label></div><button id="compare-prices" class="button secondary" type="button">Preisstände vergleichen</button><div id="price-compare-result" class="notice" hidden></div></details>`:''}</details></div>`;}
function backupPanel(){return `<div class="settings-block backup-panel"><div class="settings-block-head"><div><h3>Backup &amp; Wiederherstellung</h3><p>Exportiere Einstellungen, Verlauf und persönliche Metadaten in eine lokale Sicherung.</p></div></div><div class="backup-actions"><button id="create-backup" class="button" type="button">Backup erstellen</button><label class="button secondary" for="restore-backup">Backup wiederherstellen</label><input id="restore-backup" type="file" accept=".gz,application/gzip" hidden></div><p class="tiny muted">Maximal 64 MB komprimiert und 256 MB entpackt. Vor jeder Wiederherstellung wird automatisch ein Rückfallstand angelegt.</p></div>`;}
function bridgePanel(){
 const limit=data?.limits?.claude,live=limit?.source==='statusline';
 return `<div class="settings-block" data-provider-setting="claude"><div class="settings-block-head"><div><h3>Claude-Limits aktuell halten</h3><p>Die optionale Statusline-Bridge übernimmt bei jedem Rendern einen frischen Messwert.</p></div><span class="status-pill ${live?'is-active':''}">${live?'Aktiv':'Optional'}</span></div><div class="notice compact-notice">${live?`Letzter Messwert ${esc(date(limit.observedAt))}.`:'Ohne Bridge können die Werte aus .claude.json mehrere Tage alt sein.'}</div><div class="settings-inline-action"><p class="help">Einrichtung für eine neue oder bereits vorhandene Claude-Code-Statusline.</p><button id="bridge-help" class="button secondary" type="button" aria-haspopup="dialog">Bridge einrichten</button></div></div>`;
}
function bridgeSetupDetail(){
 const script=config.bridgeScript||'',file=data?.claudeBridge?.file||'…',command=`node "${script}"`;
 const fresh=JSON.stringify({statusLine:{type:'command',command}},null,2);
 const before=`"command": ${JSON.stringify('bash mein-skript.sh')}`;
 const after=`"command": ${JSON.stringify(`${command} -- bash mein-skript.sh`)}`;
 showDetail(`${detailHeader('Statusline-Bridge einrichten','settings.json von Claude Code · zwei Varianten')}<div class="detail-body"><p class="detail-intro">Claude Code übergibt seiner Statusline bei jedem Rendern die aktuellen Limitwerte. Die Bridge greift genau diese ab und verwirft alle übrigen Felder. Diese App sucht die Datei unter <strong>${esc(file)}</strong>; dorthin schreibt die Bridge standardmäßig auch. Ohne sie stammen die Prozentwerte aus <strong>.claude.json</strong> und können mehrere Tage alt sein.</p><h3>Variante 1 · noch keine Statusline eingerichtet</h3><p class="tiny muted">Diesen Block in die settings.json übernehmen. Die Bridge gibt dann selbst eine kompakte Zeile aus: Modell, 5-Stunden-Wert und Wochenwert.</p><pre class="code price-example">${esc(fresh)}</pre><h3>Variante 2 · vorhandene Statusline behalten</h3><p class="tiny muted">Den bisherigen Befehl hinter <strong>--</strong> stellen. Die Bridge reicht die unveränderte Eingabe durch und überlässt ihm die Ausgabe; sichtbar ändert sich nichts.</p><pre class="code price-example">Vorher:\n${esc(before)}\n\nNachher:\n${esc(after)}</pre><div class="notice">Unter Windows kann ein blosses <strong>bash</strong> über den PATH auf die WSL-Bash zeigen, die Pfade wie /c/Users/… nicht findet. Sicherer ist der absolute Pfad zur gewünschten Bash; in der Git-Bash liefert ihn <strong>cygpath -w $(which bash)</strong>.</div><h3>Schalter der Bridge</h3><dl class="detail-meta"><div><dt>-- &lt;Befehl&gt;</dt><dd>Reicht die Eingabe weiter; der Befehl gibt die Zeile aus</dd></div><div><dt>--quiet</dt><dd>Schreibt nur die Datei und gibt nichts aus</dd></div><div><dt>ATLAS_RATE_LIMIT_FILE</dt><dd>Zieldatei umlegen, falls sie nicht am gesuchten Ort landet</dd></div><div><dt>Ohne Argument</dt><dd>Schreibt die Datei und gibt die eigene kompakte Zeile aus</dd></div></dl><div class="notice format-note">Fehler bleiben folgenlos: Bei ungültiger Eingabe, fehlenden Limitfeldern oder nicht startbarem Folgebefehl schreibt die Bridge nichts und endet mit Code 0, damit die Statusline nicht bricht.</div></div>`);
}
function settingsView(){const s=config.settings,localStart=s.priceEffectiveFrom?new Date(s.priceEffectiveFrom).toISOString().slice(0,16):'',rootCount=s.claudeRoots.length+s.codexRoots.length;return `<div class="settings-shell"><aside class="panel settings-index" aria-label="Einstellungsbereiche"><div class="settings-index-intro"><span class="settings-index-mark" aria-hidden="true">⌁</span><div><strong>Einstellungen</strong><span>${num(rootCount)} Quellordner</span></div></div><div class="settings-index-links"><button type="button" data-settings-target="settings-general"><span aria-hidden="true">◌</span><span>Allgemein<small>Scan &amp; Darstellung</small></span></button><button type="button" data-settings-target="settings-sources"><span aria-hidden="true">▱</span><span>Datenquellen<small>Claude Code &amp; Codex</small></span></button><button type="button" data-settings-target="settings-prices"><span aria-hidden="true">◇</span><span>Modellpreise<small>Bewertung &amp; Verlauf</small></span></button><button type="button" data-settings-target="settings-limits"><span aria-hidden="true">◫</span><span>Limits<small>Schwellen &amp; Bridge</small></span></button><button type="button" data-settings-target="settings-data"><span aria-hidden="true">□</span><span>Datenverwaltung<small>Cache &amp; Backup</small></span></button><button type="button" data-settings-target="settings-system"><span aria-hidden="true">⚙</span><span>System<small>Autostart &amp; App</small></span></button></div></aside><form id="settings-form" class="settings-panel"><section id="settings-general" class="panel settings-section"><div class="settings-section-head"><span class="settings-section-icon" aria-hidden="true">◌</span><div><h2>Allgemein</h2><p>Lege fest, wie Session Atlas aktualisiert wird und sich in diesem Browser verhält.</p></div></div><div class="settings-block settings-row"><div><h3>Automatische Aktualisierung</h3><p>Der Scan pausiert, wenn das Fenster nicht aktiv ist. Ein laufender Scan wird beendet.</p></div><label class="compact-field"><span>Intervall</span><span class="input-suffix"><input id="interval" type="number" min="10" max="3600" step="1" value="${s.intervalSeconds}" required><span>Sek.</span></span></label></div><div class="settings-block"><div class="setting-switch"><div><h3>Animierter Hintergrund</h3><p>Bewegte Lichtpartikel in den Farben deiner KI-Tools.</p></div><button id="background-toggle" class="switch" type="button" role="switch" aria-label="Animierter Hintergrund" aria-checked="${background.enabled}"></button></div><div class="settings-inline-fields"><label class="background-quality"><span>Bewegungsqualität</span><select id="background-fps" aria-describedby="background-fps-help">${BACKGROUND_FPS_OPTIONS.map(value=>`<option value="${value}" ${background.fps===value?'selected':''}>${value==='monitor'?'Monitor-Maximum':`${value} FPS`}</option>`).join('')}</select></label><div><p id="background-fps-help" class="tiny muted">30 FPS spart Ressourcen; höhere Werte wirken flüssiger.</p><p id="background-status" class="tiny muted" role="status">${background.status}</p></div></div><p class="settings-immediate">Änderungen wirken sofort und gelten nur in diesem Browser.</p></div></section><section id="settings-sources" class="panel settings-section"><div class="settings-section-head"><span class="settings-section-icon" aria-hidden="true">▱</span><div><h2>Datenquellen</h2><p>Ein absoluter Pfad pro Zeile. Unterordner und Subagents werden automatisch berücksichtigt.</p></div></div><div class="source-grid"><label class="source-card codex-source"><span class="source-name"><span class="tool-logo">O</span>OpenAI Codex</span><textarea id="codex-roots" rows="4" spellcheck="false">${esc(s.codexRoots.join('\n'))}</textarea><span class="help">Aktive und archivierte Sessions werden zusammen ausgewertet.</span></label><label class="source-card claude-source"><span class="source-name"><span class="tool-logo claude">C</span>Claude Code</span><textarea id="claude-roots" rows="4" spellcheck="false">${esc(s.claudeRoots.join('\n'))}</textarea><span class="help">Standard ist dein .claude/projects-Ordner, inklusive Subagents.</span></label></div></section><section id="settings-prices" class="panel settings-section"><div class="settings-section-head"><span class="settings-section-icon" aria-hidden="true">◇</span><div><h2>Modellpreise</h2><p>Steuere, mit welchem Preisstand Session Atlas deine lokale Nutzung bewertet.</p></div></div><div class="settings-block"><div class="field-grid"><label>Bewertungsmodus<select id="pricing-mode"><option value="current" ${s.pricingMode==='current'?'selected':''}>Aktuelle Preise</option><option value="historical" ${s.pricingMode==='historical'?'selected':''}>Historisch hinterlegte Preise</option></select><span class="help">Historisch nutzt den zum Ereigniszeitpunkt lokal gültigen Stand.</span></label><label>Manuelle Preise gültig ab<input id="price-effective-from" type="datetime-local" value="${esc(localStart)}"><span class="help">Leer bedeutet: ab dem Speichern.</span></label></div><div class="price-help-row"><p class="help">Eigene Preise in USD pro Million Tokens. Der Modellname muss exakt dem Log entsprechen.</p><button id="price-format-help" class="info-button" type="button" aria-haspopup="dialog"><span aria-hidden="true">i</span> Format &amp; Beispiel</button></div><textarea id="prices" class="price-editor" rows="7" spellcheck="false" aria-label="Eigene Modellpreise als JSON">${esc(JSON.stringify(s.prices,null,2))}</textarea><div class="settings-meta-row"><span>Basispreise vom ${data?.priceDate||'2026-09-11'} · API-Schätzwerte</span><span class="sources"><a href="https://developers.openai.com/api/docs/pricing" target="_blank" rel="noreferrer">OpenAI</a><a href="https://platform.claude.com/docs/en/about-claude/pricing" target="_blank" rel="noreferrer">Anthropic</a></span></div><details class="settings-disclosure"><summary>Effektive Preise anzeigen</summary><pre id="effective-prices" class="code">${esc(JSON.stringify(config.rates,null,2))}</pre></details></div><div class="settings-block settings-row"><div><h3>Öffentliche Preise aktualisieren</h3><p>Ruft LiteLLM und models.dev ab. Manuelle Einträge behalten Vorrang; Sessiondaten werden nicht übertragen.</p><p id="price-sync-status" class="help" role="status"></p><div id="price-sync-notice" class="notice compact-notice" role="status" hidden></div></div><button id="sync-prices" class="button secondary" type="button">Preise aktualisieren</button></div>${priceHistoryPanel()}</section><section id="settings-limits" class="panel settings-section"><div class="settings-section-head"><span class="settings-section-icon" aria-hidden="true">◫</span><div><h2>Limits</h2><p>Bestimme Aufbewahrung und Warnschwellen für deine Codex- und Claude-Limits.</p></div></div><div id="limit-settings-slot"></div>${bridgePanel()}</section><section id="settings-data" class="panel settings-section"><div class="settings-section-head"><span class="settings-section-icon" aria-hidden="true">□</span><div><h2>Datenverwaltung</h2><p>Deine Auswertung bleibt lokal. Prompts und Antworten landen nicht im Cache.</p></div></div><div class="settings-block"><div class="settings-block-head"><div><h3>Lokaler Cache</h3><p>Historische Nutzungsdaten bleiben erhalten, auch wenn ursprüngliche Logs später fehlen.</p></div><span class="status-pill is-active">Lokal</span></div><div class="code data-path">${esc(config.dataDir)}</div><div class="settings-inline-action"><p class="help">Neu aufbauen liest alle verfügbaren Logs erneut ein. Zuvor wird ein Rückfall-Backup erstellt.</p><button id="reset-cache" class="button secondary danger-button" type="button">Cache neu aufbauen</button></div></div>${backupPanel()}</section><section id="settings-system" class="panel settings-section"><div class="settings-section-head"><span class="settings-section-icon" aria-hidden="true">⚙</span><div><h2>System</h2><p>Steuere den lokalen Start und selten benötigte App-Aktionen.</p></div></div><div class="settings-block"><div class="setting-switch"><div><h3>Windows-Autostart</h3><p>Session Atlas bei der Anmeldung starten und im Browser öffnen.</p></div><button id="startup" class="switch" type="button" role="switch" aria-label="Windows-Autostart" aria-checked="${config.startup.enabled}" ${!config.startup.supported?'disabled':''}></button></div><p class="settings-immediate">${config.startup.supported?'Die Verknüpfung verweist auf diesen Ordner. Nach einem Umzug bitte neu aktivieren.':'Auf diesem Betriebssystem ist Windows-Autostart nicht verfügbar.'}</p></div><div class="settings-block settings-row"><div><h3>Portable weitergeben</h3><p>Mit <strong>npm run package</strong> ein ZIP ohne persönliche Daten erstellen. Node.js 22+ genügt.</p></div><span class="status-pill">Ohne Installation</span></div><div class="settings-block danger-panel settings-row"><div><h3>App beenden</h3><p>Beendet den lokalen Node-Prozess vollständig. Der Neustart erfolgt über <strong>Start.cmd</strong>.</p></div><button id="shutdown" class="button secondary danger-button" data-shutdown type="button">App vollständig beenden</button></div></section><div class="settings-savebar"><p><strong>Noch nicht gespeichert?</strong><span>Pfade, Intervall, Preise und Limits werden gemeinsam übernommen.</span></p><button type="submit" class="button">Änderungen speichern</button></div></form></div>`;}
function comparisonMarkup(currentSessions){
 if(!comparisonEnabled||view!=='overview')return '';
 const currentRange=bounds(),previousRange=comparisonRange(currentRange,$('#comparison-mode').value,{from:$('#comparison-from').value,to:$('#comparison-to').value});
 if(!previousRange)return '<div class="notice">Für den Gesamtverlauf oder einen unvollständigen eigenen Zeitraum ist kein Vergleich möglich.</div>';
 return comparisonView({currentSessions,previousSessions:filtered(previousRange),currentRange,previousRange,metric:comparisonMetric,dimension:comparisonDimension,sortKey:comparisonSort,sortDirection:comparisonSortDirection,esc,num,compact,money,basename,toolName});
}
async function limitHistoryDetail(tool){limitHistoryTool=tool;let history=limitHistoryCache.get(tool);if(!history){showDetail(`${detailHeader(`${toolName(tool)} · Kostenlimits`,'Messpunkte werden geladen',toolTag(tool))}<div class="detail-body"><p class="detail-intro">Limit- und Kostendaten werden zusammengeführt …</p></div>`,{wide:true});try{const result=await api(`/api/limit-history?tool=${encodeURIComponent(tool)}`);history=result.history;limitHistoryCache.set(tool,history);}catch(err){error(`Limitverlauf konnte nicht geladen werden: ${err.message}`);return;}if(limitHistoryTool!==tool||!$('#detail').open)return;}const context=limitHistoryMode==='cost'?'Auf 100 % hochgerechneter API-Gegenwert · historischer Verlauf':'Gemessene Usage · getrennt an Resetgrenzen';showDetail(`${detailHeader(`${toolName(tool)} · Kostenlimits`,context,toolTag(tool))}${limitHistoryView({history,sessions:data.sessions,tool,mode:limitHistoryMode,aggregation:limitHistoryAggregation,sortKey:limitHistorySort,sortDirection:limitHistorySortDirection,period:limitHistoryPeriod,from:limitHistoryFrom,to:limitHistoryTo,visibleWindows:[...limitHistoryVisibleWindows],esc,date,money})}`,{wide:true});}
function limitSettingsMarkup(){const s=config.settings,values=(tool,minutes)=>(s.limitThresholds?.[tool]?.[minutes]||[80,95]).join(', ');return `<div class="settings-block"><div class="settings-row limit-retention-row"><div><h3>Limitverlauf aufbewahren</h3><p>Messpunkte bilden die Entwicklung deiner verfügbaren Kontingente ab.</p></div><label class="compact-field"><span>Aufbewahrung</span><span class="input-suffix"><input id="limit-retention" type="number" min="30" max="3650" value="${s.limitRetentionDays||90}" required><span>Tage</span></span></label></div><details class="settings-disclosure limit-settings"><summary>Warnschwellen anpassen</summary><p class="help">Hinweise erscheinen pro Schwelle und Resetfenster nur einmal.</p><div class="limit-threshold-grid">${[['codex','Codex'],['claude','Claude Code']].flatMap(([tool,name])=>[[300,'5 Stunden'],[10080,'Wöchentlich']].map(([minutes,window])=>`<label data-provider-setting="${tool}">${name} · ${window}<input id="threshold-${tool}-${minutes}" value="${esc(values(tool,minutes))}" aria-label="Schwellen ${name} ${window}"><span class="help">Prozentwerte, kommagetrennt</span></label>`)).join('')}</div></details></div>`;}
function mountProviderSettings(){const section=$('#settings-general');if(!section||section.querySelector('[data-provider-settings]'))return;const hidden=new Set(config.settings.hiddenProviders||[]),markup=`<div class="settings-block" data-provider-settings><div><h3>Sichtbare Provider</h3><p>Blendet alle Nutzungsdaten, Diagramme, Limits und Filter des jeweiligen Providers aus. Die lokalen Daten bleiben erhalten.</p></div><div class="provider-visibility">${providerOrder.map(tool=>`<div class="provider-visibility-item">${toolTag(tool)}<button class="switch" type="button" role="switch" data-provider-visibility="${tool}" aria-label="${toolName(tool)} anzeigen" aria-checked="${!hidden.has(tool)}"></button></div>`).join('')}<p class="provider-visibility-note">Standardmäßig sind beide Provider sichtbar. Die Änderung wird mit den übrigen Einstellungen gespeichert.</p></div></div>`;section.querySelector('.settings-section-head').insertAdjacentHTML('afterend',markup);for(const tool of providerOrder){document.querySelectorAll(`.${tool}-source,[data-provider-setting="${tool}"]`).forEach(element=>element.hidden=hidden.has(tool));}const tools=activeTools(),count=tools.length,sourceSection=$('#settings-sources'),sourceLink=document.querySelector('[data-settings-target="settings-sources"]');$('.source-grid')?.classList.toggle('single-column',count<2);$('.limit-threshold-grid')?.classList.toggle('single-column',count<2);if(sourceSection)sourceSection.hidden=!count;if(sourceLink){sourceLink.hidden=!count;const detail=sourceLink.querySelector('small');if(detail)detail.textContent=count===2?'Claude Code & Codex':count===1?toolName(tools[0]):'';}const limitDetails=$('.limit-settings');if(limitDetails)limitDetails.hidden=!count;const limitIntro=$('#settings-limits .settings-section-head p');if(limitIntro)limitIntro.textContent=count===1?`Bestimme Aufbewahrung und Warnschwellen für ${toolName(tools[0])}.`:count===2?'Bestimme Aufbewahrung und Warnschwellen für deine Codex- und Claude-Limits.':'Bestimme, wie lange vorhandene Limitdaten aufbewahrt werden.';const saveNote=$('.settings-savebar span');if(saveNote)saveNote.textContent='Provider, Pfade, Intervall, Preise und Limits werden gemeinsam übernommen.';}
function providerEmpty(){return `<section class="panel empty"><span aria-hidden="true">◫</span><h2>Alle Provider sind ausgeblendet</h2><p>Aktiviere OpenAI Codex oder Claude Code in den Einstellungen, um Nutzungsdaten anzuzeigen.</p><a class="button" href="#settings">Provider einblenden</a></section>`;}
function render(){if(!data&&view!=='settings')return;const title=titles[view],tools=activeTools();$('#page-title').textContent=title;$('#breadcrumb').textContent=title;document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#filters').hidden=view==='settings'||!tools.length;$('#export').hidden=view==='settings'||!tools.length;$('#shutdown-overview').hidden=view!=='overview';
 $('#compare-toggle').hidden=view!=='overview';$('#compare-controls').hidden=view!=='overview'||!comparisonEnabled;$('#compare-toggle').classList.toggle('active',comparisonEnabled);$('#compare-toggle').setAttribute('aria-pressed',String(comparisonEnabled));
 if(view==='settings'){// Preserve unsaved edits during background refreshes.
  if(!$('#settings-form')){$('#content').innerHTML=settingsView();$('#limit-settings-slot').innerHTML=limitSettingsMarkup();mountProviderSettings();}updatePriceSyncUI();
 }else if(!tools.length){$('#content').innerHTML=providerEmpty();chartSessions=null;
 }else{const sessions=filtered();const unknown=totals(sessions.flatMap(s=>s.events)).unknown;const usageMarkup=view==='overview'?(overviewVisual==='calendar'?calendar(sessions):chart(sessions)):'',limitMarkup=view==='overview'?limits():'',selected=scopedSessions();const selection=view==='overview'&&selectedChartBucket?`<div class="chart-selection" role="status"><span>Daten darunter gefiltert auf <strong>${esc(bucketLabel(selectedChartBucket,chartPeriod))}</strong></span><button id="clear-chart-selection" type="button">${overviewVisual==='calendar'?'Tagesauswahl aufheben':'Alle Zeitabschnitte anzeigen'}</button></div>`:'';$('#content').innerHTML=metrics(sessions)+(unknown?`<div class="notice price-notice"><span>Für ${num(unknown)} Modellantworten fehlt ein verlässlicher Preis. Bekannte Kosten sind Untergrenzen und können höher ausfallen; zusätzlich ist die Summe unvollständig. Eigene Preise lassen sich in den <a href="#settings"><u>Einstellungen</u></a> ergänzen.</span><button class="notice-action" id="price-details">Modelle anzeigen</button></div>`:'')+comparisonMarkup(sessions)+(view==='overview'?`<div class="dashboard-grid ${overviewVisual==='calendar'?'calendar-layout':''} ${limitMarkup?'':'without-limits'}">${usageMarkup}${limitMarkup}</div>`:'')+selection+table(selected)+(view==='overview'&&selected.length?insights(selected):'');chartSessions=view==='overview'&&overviewVisual==='chart'?sessions:null;if(chartSessions)fitChart();}
 updateFilterReset();
 const st=data?.stats;$('#scan-status').textContent=data?.lastScan?`Aktualisiert ${date(data.lastScan)} · ${st?.files||0} Dateien · ${st?.changed||0} geändert · ${st?.durationMs||0} ms`:'Bereit · noch kein Scan';
 if(st?.warnings?.length){$('#scan-status').textContent+=` · ${st.warnings.length} Lese-/Cachefehler`;$('#scan-status').title=st.warnings.join('\n');}
}
function navigate(){view=location.hash.slice(1) in titles?location.hash.slice(1):'overview';page=0;group=view==='repositories'?'repository':'sessions';sort='activity';sortDirection='desc';selectedChartBucket=null;$('#content').innerHTML='';render();}
window.addEventListener('hashchange',navigate);
function showDetail(html,{wide=false}={}){$('#detail-content').innerHTML=html;const dialog=$('#detail');dialog.classList.toggle('detail-wide',wide);if(!dialog.open)dialog.showModal();}
function detailHeader(title,context,tag=''){return `<div class="detail-header"><div>${tag}<h2${tag?' style="margin-top:13px"':''}>${esc(title)}</h2><span class="tiny muted">${esc(context)}</span></div><button class="close" id="close-detail" aria-label="Details schließen">✕</button></div>`;}
function tokenDetails(t){return `<section class="metrics"><div class="metric"><div class="metric-label">Tokens gesamt</div><div class="metric-value">${compact(t.tokens)}</div></div><div class="metric"><div class="metric-label">API-Schätzung</div><div class="metric-value">${costText(t)}</div></div><div class="metric"><div class="metric-label">Modellantworten</div><div class="metric-value">${num(t.requests)}</div></div></section><h3>So verteilen sich die Tokens</h3><div class="breakdown">${['input','cache','write','output'].map(k=>`<i class="${k}" style="width:${t.tokens?t[k]/t.tokens*100:0}%"></i>`).join('')}</div><div class="breakdown-labels"><span>Input ${num(t.input)}</span><span>Cache lesen ${num(t.cache)}</span><span>Cache schreiben ${num(t.write)}</span><span>Output ${num(t.output)}</span><span>Davon Reasoning ${num(t.reasoning)}</span></div>`;}
function detail(id){const s=data.sessions.find(s=>s.id===id);if(!s)return;const t=totals(s.events),models=[...new Set(s.events.map(e=>e.model))];showDetail(`${detailHeader(s.title||basename(s.cwd),'Gesamte Session · unabhängig vom Zeitraumfilter',toolTag(s.tool))}<div class="detail-body"><dl class="detail-meta"><div><dt>Session-ID</dt><dd>${esc(s.sessionId)}${s.subagent?' (Subagent)':''}</dd></div><div><dt>Modell${models.length!==1?'e':''}</dt><dd>${esc(models.join(', ')||'Nicht protokolliert')}</dd></div><div><dt>Repository</dt><dd>${esc(s.repository)}</dd></div><div><dt>Beginn / letzte Aktivität</dt><dd>${date(s.started)} / ${date(s.lastActivity)}</dd></div><div><dt>Branch</dt><dd>${esc(s.branch||'–')}</dd></div><div><dt>Kontext laut letztem Log</dt><dd>${s.contextWindow?`${compact(s.contextUsed)} / ${compact(s.contextWindow)} Tokens`:'Nicht verfügbar'}</dd></div></dl>${tokenDetails(t)}${t.unknown?`<div class="notice">${t.unknown} Antworten ohne bekannten Preis. Bekannte Kosten sind Untergrenzen und können höher ausfallen; zusätzlich ist die Summe unvollständig.</div>`:''}${s.malformed?`<div class="notice">${s.malformed} ungültige Logzeilen wurden übersprungen.</div>`:''}<h3>Letzte Modellantworten</h3><div class="table-wrap"><table><thead><tr><th>Zeitpunkt</th><th>Modell</th><th class="numeric">Tokens</th><th class="numeric">API-Kosten</th></tr></thead><tbody>${[...s.events].sort((a,b)=>b.time.localeCompare(a.time)).slice(0,40).map(e=>`<tr><td>${date(e.time)}</td><td>${esc(e.model)}<span class="row-subtitle">${esc(e.tier)}</span></td><td class="numeric">${num(e.input+e.cache+e.write+e.output)}</td><td class="numeric">${e.cost===null?'Unbekannt':money(e.cost)}</td></tr>`).join('')||'<tr><td colspan="4">Diese Session enthält noch keine Nutzungsmetriken.</td></tr>'}</tbody></table></div></div>`);}
function aggregateDetail(kind,key){const sessions=filtered();const row=grouped(sessions,kind).find(r=>r.name===key);if(!row)return;const selected=sessions.filter(s=>kind==='repository'?s.repository===key:kind==='tool'?s.tool===key:s.events.some(e=>e.model===key)).map(s=>({...s,events:kind==='model'?s.events.filter(e=>e.model===key):s.events}));const sessionRows=selected.map(s=>({...s,...totals(s.events)})).sort((a,b)=>(b.lastActivity||'').localeCompare(a.lastActivity||''));const labels={repository:'Repository',tool:'KI-Tool',model:'Modell'},title=kind==='repository'?basename(key):kind==='tool'?toolName(key):key;const models=[...new Set(row.events.map(e=>e.model))],repos=[...new Set(selected.map(s=>s.repository))];showDetail(`${detailHeader(title,`${labels[kind]} · aktuelle Filter und gewählter Zeitraum`,kind==='tool'?toolTag(key):'')}<div class="detail-body"><dl class="detail-meta"><div><dt>Sessions</dt><dd>${num(row.sessions.size)}</dd></div><div><dt>KI-Tools</dt><dd>${[...row.tools].map(toolName).join(', ')}</dd></div><div><dt>${kind==='model'?'Repositories':'Modelle'}</dt><dd>${esc((kind==='model'?repos.map(basename):models).join(', ')||'Nicht protokolliert')}</dd></div><div><dt>Erste / letzte Aktivität</dt><dd>${date(row.firstActivity)} / ${date(row.lastActivity)}</dd></div></dl>${tokenDetails(row)}${row.unknown?`<div class="notice">${num(row.unknown)} Antworten ohne bekannten Preis. Bekannte Kosten sind Untergrenzen und können höher ausfallen; zusätzlich ist die Summe unvollständig.</div>`:''}<h3>Zugehörige Sessions</h3><div class="table-wrap"><table><thead><tr><th>Session</th><th>KI-Tool</th><th class="numeric">Antworten</th><th class="numeric">Tokens</th><th class="numeric">API-Kosten</th></tr></thead><tbody>${sessionRows.slice(0,40).map(s=>`<tr><td><button class="row-button" data-session="${esc(s.id)}"><span class="row-title">${esc(s.title||basename(s.cwd))}</span><span class="row-subtitle">${esc(basename(s.repository))}</span></button></td><td>${toolTag(s.tool)}</td><td class="numeric">${num(s.requests)}</td><td class="numeric">${compact(s.tokens)}</td><td class="numeric">${costText(s)}</td></tr>`).join('')}</tbody></table></div>${sessionRows.length>40?`<p class="detail-footnote">40 von ${num(sessionRows.length)} Sessions angezeigt.</p>`:''}</div>`);}
function unknownPriceDetail(){const sessions=filtered().map(s=>({...s,events:s.events.filter(e=>e.cost===null)})).filter(s=>s.events.length),rawRows=grouped(sessions,'model'),value=(row,key)=>key==='name'?row.name:key==='tools'?[...row.tools].map(toolName).join(', '):key==='sessions'?row.sessions.size:key==='requests'?row.requests:row.tokens,rows=sortRows(rawRows,unknownPriceSort,unknownPriceSortDirection,value),head=(label,key,numeric=false)=>sortableHeader(label,key,{activeKey:unknownPriceSort,direction:unknownPriceSortDirection,context:'unknown-price',numeric}),t=totals(sessions.flatMap(s=>s.events));showDetail(`${detailHeader('Modelle ohne Preis','Aktuelle Filter und gewählter Zeitraum')}<div class="detail-body"><p class="detail-intro">Für diese Modellnamen konnte keine verlässliche Preiszuordnung gefunden werden. Die Anzahl zeigt, wie viele Modellantworten dadurch ohne Kostenschätzung bleiben.</p><div class="table-wrap unknown-models-table"><table><thead><tr>${head('Modellname','name')}${head('KI-Tools','tools')}${head('Sessions','sessions',true)}${head('Antworten ohne Preis','requests',true)}${head('Tokens','tokens',true)}</tr></thead><tbody>${rows.map(r=>`<tr><td><span class="row-title">${esc(r.name||'Nicht protokolliert')}</span></td><td>${[...r.tools].map(toolTag).join(' ')}</td><td class="numeric">${num(r.sessions.size)}</td><td class="numeric"><strong>${num(r.requests)}</strong></td><td class="numeric">${compact(r.tokens)}</td></tr>`).join('')}</tbody></table></div><div class="detail-summary">${num(rows.length)} Modellnamen · ${num(t.requests)} Antworten ohne Preis</div><a class="button secondary detail-settings-link" href="#settings">Preise in den Einstellungen ergänzen</a></div>`);}
function priceFormatDetail(){const example=JSON.stringify({'mein-modell':[3,.3,15],'mein-modell-mit-cache':[3,.3,15,3.75,6]},null,2);showDetail(`${detailHeader('Format für eigene Modellpreise','JSON · alle Beträge in USD pro Million Tokens')}<div class="detail-body"><p class="detail-intro">Jeder Eintrag besteht aus dem exakten Modellnamen und einem Array mit drei bis fünf Preisen. Dezimalzahlen werden mit einem Punkt geschrieben.</p><ol class="price-format-list"><li><strong>Input</strong><span>Normale Input-Tokens</span></li><li><strong>Cache lesen</strong><span>Wiederverwendete Input-Tokens</span></li><li><strong>Output</strong><span>Ausgabe inklusive Reasoning</span></li><li><strong>Cache schreiben, 5 Min.</strong><span>Optional; ohne Angabe gilt der Input-Preis</span></li><li><strong>Cache schreiben, 1 Std.</strong><span>Optional; ohne Angabe gilt der vorherige Schreibpreis</span></li></ol><h3>Beispiel</h3><pre class="code price-example">${esc(example)}</pre><div class="notice format-note">Das gesamte Feld muss ein gültiges JSON-Objekt sein. Verwende doppelte Anführungszeichen und kein Komma nach dem letzten Eintrag.</div></div>`);}
function backupPreviewDetail(preview){restorePreviewId=preview.restoreId;const missing=(preview.sourceRoots||[]).filter(item=>!item.available);showDetail(`${detailHeader('Backup prüfen','Noch wurde nichts verändert')}<div class="detail-body"><p class="detail-intro">Diese Wiederherstellung ersetzt den aktuellen App-Datenstand. Unmittelbar davor wird automatisch ein lokaler Rückfallstand gespeichert.</p><dl class="detail-meta"><div><dt>Erstellt</dt><dd>${date(preview.createdAt)}</dd></div><div><dt>Größe</dt><dd>${num(preview.compressedBytes)} Byte komprimiert / ${num(preview.uncompressedBytes)} Byte entpackt</dd></div><div><dt>Sessions</dt><dd>${num(preview.sessionCount)}</dd></div><div><dt>Formatversion</dt><dd>${num(preview.version)}</dd></div></dl><h3>Enthaltene Kategorien</h3><ul>${preview.categories.map(item=>`<li>${esc(item.label)}</li>`).join('')}</ul>${missing.length?`<h3>Nicht gefundene Quellordner</h3><p class="help">Die gesicherte Historie bleibt auch ohne Zuordnung lesbar. Optional kannst du hier den entsprechenden absoluten Ordner auf diesem Rechner eintragen.</p><div class="restore-mappings">${missing.map(item=>`<label><span>${esc(item.tool==='codex'?'Codex':'Claude Code')} · ${esc(item.path)}</span><input data-root-mapping="${esc(item.path)}" placeholder="Neuer absoluter Pfad (optional)" spellcheck="false"></label>`).join('')}</div>`:''}<div class="notice">Pfade und Sessiontitel können persönliche Informationen enthalten. Original-Logdateien sind nicht Bestandteil der Sicherung.</div><button class="button danger-button" data-restore-confirm type="button">Diesen Datenstand wiederherstellen</button></div>`);}
function restoreMappings(){return Object.fromEntries([...document.querySelectorAll('#detail [data-root-mapping]')].map(input=>[input.dataset.rootMapping,input.value.trim()]).filter(([,value])=>value));}
async function downloadBackup(){const button=$('#create-backup');if(button)button.disabled=true;try{const response=await binaryApi('/api/backup/export','{}'),blob=await response.blob(),disposition=response.headers.get('Content-Disposition')||'',name=disposition.match(/filename="([^"]+)"/)?.[1]||`session-atlas-backup-${day(Date.now())}.json.gz`,url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Vollständiges lokales Backup erstellt.');}catch(err){error(`Backup fehlgeschlagen: ${err.message}`);}finally{if(button)button.disabled=false;}}
async function loadSessionDetails(id){const requestedData=data,revision=requestedData?.detailRevision,session=requestedData?.sessions.find(item=>item.id===id);if(!session)return;const key=`${id}|${revision||''}`;let detailed=sessionDetailCache.get(key);if(!detailed){try{const result=await api(`/api/session-details?id=${encodeURIComponent(id)}`);if(data!==requestedData||result.detailRevision!==revision)return;detailed=result.session;if(sessionDetailCache.size>=50)sessionDetailCache.delete(sessionDetailCache.keys().next().value);sessionDetailCache.set(key,detailed);}catch(err){error(`Sessiondetails konnten nicht geladen werden: ${err.message}`);throw err;}}if(data!==requestedData||data?.detailRevision!==revision)return;const current=data.sessions.find(item=>item.id===id);if(current)Object.assign(current,detailed);return detailed;}
detailViews=createDetailViews({
 dialog:$('#detail'),content:$('#detail-content'),getData:()=>data,getFiltered:()=>scopedSessions(),
 getScope:()=>({...filterScope(),period:$('#period').value,selectedChartLabel:view==='overview'&&selectedChartBucket?bucketLabel(selectedChartBucket,chartPeriod):null}),
 applyFilter:(kind,key)=>{
  if(kind==='repository')$('#repository').value=key;else if(kind==='tool')$('#tool').value=key;else if(kind==='model')$('#model').value=key;else $('#search').value=key;
  page=0;render();
 },
 loadSessionDetails,esc,num,compact,money,date,basename,toolName,toolTag,costText
});
async function csvExport(){const button=$('#export');button.disabled=true;try{const full=await api('/api/export-data'),sessions=filterSessions(visibleSessions(full.sessions),filterScope(),bounds()),header=['session_id','tool','repository','folder','model','timestamp','input_tokens','cached_tokens','cache_write_tokens','output_tokens','reasoning_tokens','estimated_usd','pricing_mode','price_snapshot_id','pricing_rule_version'];const rows=sessions.flatMap(s=>s.events.map(e=>[s.sessionId,toolName(s.tool),s.repository,s.cwd,e.model,e.time,e.input,e.cache,e.write,e.output,e.reasoning,e.cost===null?'':e.cost.toFixed(6),e.pricingMode||full.pricingMode||'current',e.priceSnapshotId||'',e.pricingRuleVersion||full.pricingRuleVersion||'']));const cell=v=>{let str=String(v??'');if(/^[=+\-@\t\r]/.test(str))str="'"+str;return '"'+str.replaceAll('"','""')+'"';};const text='\uFEFF'+[header,...rows].map(r=>r.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`session-atlas-${day(Date.now())}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${num(rows.length)} Nutzungsereignisse exportiert.`);}catch(err){error(`CSV-Export fehlgeschlagen: ${err.message}`);}finally{button.disabled=false;}}
async function shutdownApp(){if(!confirm('Session Atlas vollständig beenden?'))return;const buttons=[...document.querySelectorAll('[data-shutdown]')];buttons.forEach(button=>button.disabled=true);try{await api('/api/shutdown',{});polling.stop();background.stop();config=null;$('#live-status').textContent='Beendet';$('#live-status').classList.add('paused');$('#refresh').disabled=true;toast('App beendet. Zum Starten Start.cmd öffnen.');}catch(err){buttons.forEach(button=>button.disabled=false);error(err.message);}}
function updateThemeControls(){document.querySelectorAll('[data-theme-choice]').forEach(button=>{const selected=button.dataset.themeChoice===theme;button.setAttribute('aria-pressed',String(selected));button.classList.toggle('active',selected);});}
updateThemeControls();$('.theme-options').addEventListener('click',e=>{const button=e.target.closest('[data-theme-choice]');if(!button)return;theme=themeValues.has(button.dataset.themeChoice)?button.dataset.themeChoice:'system';document.documentElement.dataset.theme=theme;updateThemeControls();try{if(theme==='system')localStorage.removeItem('session-atlas-theme');else localStorage.setItem('session-atlas-theme',theme);}catch{}});
$('#refresh').addEventListener('click',()=>refresh(true));$('#export').addEventListener('click',csvExport);$('#shutdown-overview').addEventListener('click',shutdownApp);
$('#reset-filter-selection').addEventListener('click',()=>{clearSelectionFilters();page=0;render();});
for(const id of ['tool','repository','model','period','from','to'])$('#'+id).addEventListener('change',event=>{$('#custom-dates').hidden=$('#period').value!=='custom';if(overviewVisual==='calendar'&&['period','from','to'].includes(event.target.id))calendarRangeMode='selection';selectedChartBucket=null;page=0;render();});
$('#compare-toggle').addEventListener('click',()=>{if(!comparisonEnabled&&bounds().start===0){toast('Wähle zuerst einen begrenzten Zeitraum.');return;}comparisonEnabled=!comparisonEnabled;render();});
for(const id of ['comparison-mode','comparison-from','comparison-to'])$('#'+id).addEventListener('change',()=>{$('#comparison-custom-dates').hidden=$('#comparison-mode').value!=='custom';render();});
let searchTimer;$('#search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page=0;render();},160);});
$('#content').addEventListener('change',e=>{if(e.target.id==='group'){group=e.target.value;sort='activity';sortDirection='desc';page=0;render();}if(e.target.id==='calendar-range'){calendarRangeMode=e.target.value;if(calendarRangeMode==='rolling'){$('#period').value='12months';$('#custom-dates').hidden=true;}else if(/^\d{4}$/.test(calendarRangeMode)){$('#period').value='custom';$('#from').value=`${calendarRangeMode}-01-01`;$('#to').value=`${calendarRangeMode}-12-31`;$('#custom-dates').hidden=false;}selectedChartBucket=null;page=0;render();}});
attachTooltips($('#content'));
$('#content').addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.providerVisibility){el.setAttribute('aria-checked',String(el.getAttribute('aria-checked')!=='true'));return;}if(el.dataset.limitHistory){limitHistoryMode='cost';limitHistoryAggregation='window';limitHistoryPeriod='30';limitHistoryFrom=day(Date.now()-29*86400000);limitHistoryTo=day(Date.now());limitHistoryVisibleWindows=new Set([300,10080]);}
 if(el.dataset.overviewVisual){overviewVisual=el.dataset.overviewVisual;if(overviewVisual==='calendar'&&calendarRangeMode==='selection'){$('#period').value='12months';$('#custom-dates').hidden=true;calendarRangeMode='rolling';}selectedChartBucket=null;page=0;render();}if(el.dataset.calendarMetric){calendarMetric=el.dataset.calendarMetric;render();}if(el.dataset.metric){chartMetric=el.dataset.metric;render();}if(el.dataset.bucket){chartPeriod=el.dataset.bucket;selectedChartBucket=null;render();}if(el.dataset.comparisonMetric){comparisonMetric=el.dataset.comparisonMetric;render();}if(el.dataset.comparisonDimension){comparisonDimension=el.dataset.comparisonDimension;comparisonSort='delta';comparisonSortDirection='desc';render();}if(el.dataset.sortContext==='main'){const next=nextSort(sort,sortDirection,el.dataset.sortKey,el.dataset.sortDefault);sort=next.key;sortDirection=next.direction;page=0;render();}if(el.dataset.sortContext==='comparison'){const next=nextSort(comparisonSort,comparisonSortDirection,el.dataset.sortKey,el.dataset.sortDefault);comparisonSort=next.key;comparisonSortDirection=next.direction;render();}if(el.dataset.comparisonFilter){const kind=el.dataset.comparisonFilter,value=el.dataset.comparisonValue,control=kind==='repository'?$('#repository'):kind==='tool'?$('#tool'):kind==='model'?$('#model'):null;if(control)control.value=control.value===value?'all':value;page=0;render();}if(el.dataset.session)detailViews.session(el.dataset.session);if(el.dataset.groupKind)detailViews.aggregate(el.dataset.groupKind,el.dataset.groupKey);if(el.dataset.limitHistory){limitHistorySort='observed';limitHistorySortDirection='desc';limitHistoryDetail(el.dataset.limitHistory);}if(el.id==='price-details'){unknownPriceSort='requests';unknownPriceSortDirection='desc';unknownPriceDetail();}if(el.id==='price-format-help')priceFormatDetail();if(el.id==='bridge-help')bridgeSetupDetail();if(el.dataset.page){page+=Number(el.dataset.page);render();}if(el.id==='clear-chart-selection'){selectedChartBucket=null;page=0;render();}
 if(el.id==='reset-filters'){resetAllFilters();page=0;render();}
 if(el.id==='reset-cache'){
  if(!confirm('Den lokalen Auswertungscache vollständig neu aufbauen? Historische Daten aus inzwischen gelöschten Logdateien entfallen. Vorher wird automatisch ein Rückfall-Backup erstellt.'))return;
  el.disabled=true;try{const result=await api('/api/cache/reset',{});data=result.snapshot;limitHistoryCache.clear();sessionDetailCache.clear();$('#detail').close();$('#content').innerHTML='';updateFilters();render();const warnings=data.stats?.warnings?.length||0;toast(warnings?`Cache neu aufgebaut · ${num(warnings)} Warnungen beim Einlesen.`:'Cache neu aufgebaut · Rückfall-Backup gespeichert.');error('');}catch(err){error(`Cache konnte nicht neu aufgebaut werden: ${err.message}`);el.disabled=false;}return;
 }
 if(el.id==='sync-prices'){
  if(priceSyncBusy)return;
  priceSyncBusy=true;priceSyncMessage='';updatePriceSyncUI();
  try{
   const result=await api('/api/prices/sync',{});
   config.pricing=result.pricing;config.rates=result.rates;config.priceHistory=result.priceHistory;
   priceSyncMessage=result.warnings.length?'Teilweise aktualisiert. '+result.warnings.join(' · '):'';
   toast(result.warnings.length?'Preise teilweise aktualisiert.':'Preise aktualisiert und lokal gespeichert.');
   data=await api('/api/snapshot');render();
  }catch(err){priceSyncMessage=err.message;}
  finally{priceSyncBusy=false;updatePriceSyncUI();}
 }
 if(el.id==='create-backup')await downloadBackup();
 if(el.id==='compare-prices'){el.disabled=true;const resultBox=$('#price-compare-result');try{const result=await api('/api/prices/compare',{first:$('#price-compare-first').value,second:$('#price-compare-second').value,from:$('#price-compare-from').value,to:$('#price-compare-to').value}),difference=result.second.cost-result.first.cost;resultBox.innerHTML=`Erster Stand: <strong>${money(result.first.cost)}</strong>${result.first.unknown?` · ${num(result.first.unknown)} unbekannt`:''}<br>Zweiter Stand: <strong>${money(result.second.cost)}</strong>${result.second.unknown?` · ${num(result.second.unknown)} unbekannt`:''}<br>Preiseffekt: <strong>${difference>=0?'+':''}${money(difference)}</strong> bei ${num(result.first.events)} Modellantworten.`;resultBox.hidden=false;}catch(err){resultBox.textContent=err.message;resultBox.hidden=false;}finally{el.disabled=false;}}
 if(el.dataset.restoreConfirm!==undefined){if(!restorePreviewId||!confirm('Den aktuellen App-Datenstand jetzt durch das geprüfte Backup ersetzen?'))return;el.disabled=true;try{const result=await api('/api/backup/restore',{restoreId:restorePreviewId,rootMappings:restoreMappings()});config.settings=result.settings;config.pricing=result.pricing;config.priceHistory=result.priceHistory;config.rates=result.rates;config.activeState=result.activeState;data=result.snapshot;limitHistoryCache.clear();sessionDetailCache.clear();restorePreviewId='';$('#detail').close();$('#content').innerHTML='';updateFilters();render();toast('Backup wiederhergestellt. Ein automatischer Rückfallstand wurde angelegt.');}catch(err){error(`Wiederherstellung fehlgeschlagen: ${err.message}`);el.disabled=false;}}
 if(el.id==='startup'){el.disabled=true;try{config.startup=await api('/api/startup',{enabled:!config.startup.enabled});el.setAttribute('aria-checked',String(config.startup.enabled));toast(config.startup.enabled?'Windows-Autostart aktiviert.':'Windows-Autostart entfernt.');}catch(err){error(err.message);}finally{el.disabled=false;}}
  if(el.matches('[data-shutdown]'))await shutdownApp();
 });
function selectChartBucket(element){chartPeriod=element.dataset.chartPeriod||chartPeriod;selectedChartBucket=selectedChartBucket===element.dataset.chartBucket?null:element.dataset.chartBucket;page=0;render();}
$('#content').addEventListener('click',event=>{const settingsTarget=event.target.closest('[data-settings-target]');if(settingsTarget){document.querySelectorAll('[data-settings-target]').forEach(button=>{const active=button===settingsTarget;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','true');else button.removeAttribute('aria-current');});document.getElementById(settingsTarget.dataset.settingsTarget)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return;}const bucket=event.target.closest('[data-chart-bucket]');if(bucket)selectChartBucket(bucket);});
$('#content').addEventListener('keydown',event=>{if(!['Enter',' '].includes(event.key))return;const bucket=event.target.closest('[data-chart-bucket]');if(!bucket)return;event.preventDefault();selectChartBucket(bucket);});
$('#content').addEventListener('change',async e=>{if(e.target.id!=='restore-backup'||!e.target.files?.[0])return;const file=e.target.files[0];if(file.size>64*1024*1024){error('Backup nicht geprüft: Die Datei überschreitet 64 MB.');return;}try{const response=await binaryApi('/api/backup/preview',await file.arrayBuffer()),preview=await response.json();backupPreviewDetail(preview);error('');}catch(err){error(`Backup nicht geprüft: ${err.message}`);}finally{e.target.value='';}});
$('#content').addEventListener('submit',async e=>{if(e.target.id!=='settings-form')return;e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const thresholds=id=>$('#'+id).value.split(',').map(value=>Number(value.trim())).filter(Number.isFinite),hiddenProviders=providerOrder.filter(tool=>$(`[data-provider-visibility="${tool}"]`)?.getAttribute('aria-checked')!=='true'),settings={intervalSeconds:Number($('#interval').value),hiddenProviders,limitRetentionDays:Number($('#limit-retention').value),limitThresholds:{codex:{300:thresholds('threshold-codex-300'),10080:thresholds('threshold-codex-10080')},claude:{300:thresholds('threshold-claude-300'),10080:thresholds('threshold-claude-10080')}},claudeRoots:$('#claude-roots').value.split('\n').map(s=>s.trim()).filter(Boolean),codexRoots:$('#codex-roots').value.split('\n').map(s=>s.trim()).filter(Boolean),prices:JSON.parse($('#prices').value),pricingMode:$('#pricing-mode').value,priceEffectiveFrom:$('#price-effective-from').value};const result=await api('/api/settings',settings);config.settings=result.settings;config.priceHistory=result.priceHistory||config.priceHistory;$('#content').innerHTML='';error('');toast('Einstellungen gespeichert.');await refresh(false);}catch(err){error(`Einstellungen nicht gespeichert: ${err.message}`);}finally{button.disabled=false;schedule();}});
$('#detail').addEventListener('click',async e=>{if(e.target.id==='detail'||e.target.closest('#close-detail')){$('#detail').close();return;}const mode=e.target.closest('[data-limit-history-mode]');if(mode){limitHistoryMode=mode.dataset.limitHistoryMode;limitHistorySort='observed';limitHistorySortDirection='desc';limitHistoryDetail(limitHistoryTool);return;}const windowToggle=e.target.closest('[data-limit-history-window]');if(windowToggle){const minutes=Number(windowToggle.dataset.limitHistoryWindow);if(limitHistoryVisibleWindows.has(minutes))limitHistoryVisibleWindows.delete(minutes);else limitHistoryVisibleWindows.add(minutes);limitHistoryDetail(limitHistoryTool);return;}const tableSort=e.target.closest('[data-sort-context]');if(tableSort?.dataset.sortContext==='limit-history'){const next=nextSort(limitHistorySort,limitHistorySortDirection,tableSort.dataset.sortKey,tableSort.dataset.sortDefault);limitHistorySort=next.key;limitHistorySortDirection=next.direction;limitHistoryDetail(limitHistoryTool);return;}if(tableSort?.dataset.sortContext==='unknown-price'){const next=nextSort(unknownPriceSort,unknownPriceSortDirection,tableSort.dataset.sortKey,tableSort.dataset.sortDefault);unknownPriceSort=next.key;unknownPriceSortDirection=next.direction;unknownPriceDetail();return;}const restore=e.target.closest('[data-restore-confirm]');if(restore){e.stopImmediatePropagation();if(!restorePreviewId||!confirm('Den aktuellen App-Datenstand jetzt durch das geprüfte Backup ersetzen?'))return;restore.disabled=true;try{const result=await api('/api/backup/restore',{restoreId:restorePreviewId,rootMappings:restoreMappings()});config.settings=result.settings;config.pricing=result.pricing;config.priceHistory=result.priceHistory;config.rates=result.rates;config.activeState=result.activeState;data=result.snapshot;limitHistoryCache.clear();sessionDetailCache.clear();restorePreviewId='';$('#detail').close();$('#content').innerHTML='';updateFilters();render();toast('Backup wiederhergestellt. Ein automatischer Rückfallstand wurde angelegt.');}catch(err){error(`Wiederherstellung fehlgeschlagen: ${err.message}`);restore.disabled=false;}return;}const session=e.target.closest('[data-session]');if(session)detail(session.dataset.session);const settings=e.target.closest('a[href="#settings"]');if(settings)$('#detail').close();});
$('#detail').addEventListener('change',e=>{if(e.target.id==='limit-history-aggregation'){limitHistoryAggregation=e.target.value==='raw'?'raw':'window';limitHistorySort='observed';limitHistorySortDirection='desc';limitHistoryDetail(limitHistoryTool);return;}if(e.target.id==='limit-history-period'){limitHistoryPeriod=e.target.value;limitHistoryDetail(limitHistoryTool);return;}if(e.target.id==='limit-history-from'||e.target.id==='limit-history-to'){limitHistoryFrom=$('#limit-history-from')?.value||limitHistoryFrom;limitHistoryTo=$('#limit-history-to')?.value||limitHistoryTo;limitHistoryDetail(limitHistoryTool);}});
async function init(){try{config=await api('/api/bootstrap');token=config.token;data=await api('/api/snapshot');updateFilters();$('#from').value=day(Date.now()-29*86400000);$('#to').value=day(Date.now());$('#comparison-from').value=day(Date.now()-59*86400000);$('#comparison-to').value=day(Date.now()-30*86400000);navigate();await refresh(false);schedule();}catch(e){error(`App konnte nicht geladen werden: ${e.message}`);$('#content').innerHTML='<div class="empty"><h2>Keine Verbindung zur lokalen App</h2><p>Starte Start.cmd und lade diese Seite neu.</p></div>';}}
init();
